        assertSame(Hours.FOUR,Hours.hours(4));
        assertSame(Hours.FIVE,Hours.hours(5));
        assertSame(Hours.SIX,Hours.hours(6));
        assertSame(Hours.SEVEN,Hours.hours(7));
        assertSame(Hours.EIGHT,Hours.hours(8));
