public void testFormat_date_oe() {
        DateTime dt = new DateTime(2004, 6, 9, 10, 20, 30, 40, UTC);
        assertEquals("2004-06-09",ISODateTimeFormat.date().print(dt));

        dt = dt.withZone(LONDON);
        assertEquals("2004-06-09",ISODateTimeFormat.date().print(dt));

        dt = dt.withZone(PARIS);
        assertEquals("2004-06-09",ISODateTimeFormat.date().print(dt));
    }

